/// The content class claiming `option` of scenery `id`, if any.
pub fn claim(id: i32, option: &str) -> Option<&'static str> {
    let at = CLAIMS.partition_point(|(i, o, _)| (*i, *o) < (id, option));
    CLAIMS
        .get(at)
        .filter(|(i, o, _)| *i == id && *o == option)
        .map(|(_, _, c)| *c)
}

/// The content class claiming `option` of the object at `at`, if any.
pub fn claim_at(at: [i32; 3], option: &str) -> Option<&'static str> {
    LOCATIONS
        .iter()
        .find(|(l, o, _)| *l == at && *o == option)
        .map(|(_, _, c)| *c)
}

/// The content plugin registered for scenery `id`, if any.
pub fn plugin(id: i32) -> Option<&'static str> {
    PLUGINS.iter().find(|(i, _)| *i == id).map(|(_, c)| *c)
}

/// The content zone whose borders hold `at` (ZoneBorders.insideBorder:
/// inclusive corners, any plane unless one is given), if any.
pub fn zone_at(at: [i32; 3]) -> Option<&'static str> {
    let [x, y, z] = at;
    let region = ((x >> 6) << 8) | (y >> 6);
    ZONE_BORDERS
        .iter()
        .find(|(_, [a, b, c, d, p])| {
            x >= *a && y >= *b && x <= *c && y <= *d && (*p < 0 || *p == z)
        })
        .map(|(c, _)| *c)
        .or_else(|| {
            ZONE_REGIONS
                .iter()
                .find(|(_, r)| *r == region)
                .map(|(c, _)| *c)
        })
}
